override fun onMeasure(widthMeasureSpec: Int, heightMeasureSpec: Int) {
    val widthMode = MeasureSpec.getMode(widthMeasureSpec)
    val widthSize = MeasureSpec.getSize(widthMeasureSpec)
    val heightMode = MeasureSpec.getMode(heightMeasureSpec)
    val heightSize = MeasureSpec.getSize(heightMeasureSpec)

    // 处理 wrap_content 情况
    val defaultWidth = 200.dp
    val defaultHeight = 200.dp

    val finalWidth = if (widthMode == MeasureSpec.AT_MOST) {
        minOf(defaultWidth, widthSize)
    } else {
        widthSize
    }

    val finalHeight = if (heightMode == MeasureSpec.AT_MOST) {
        minOf(defaultHeight, heightSize)
    } else {
        heightSize
    }

    setMeasuredDimension(finalWidth, finalHeight)
}

